export function parseCsvLine(line) {
  const fields = [];
  let current = '';
  let i = 0;

  while (i < line.length) {
    if (line[i] === '"') {
      // Quoted field
      i++; // skip opening quote
      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            current += '"';
            i += 2;
          } else {
            i++; // skip closing quote
            break;
          }
        } else {
          current += line[i];
          i++;
        }
      }
      // After a quoted field, if next is comma, skip it
      if (i < line.length && line[i] === ',') {
        fields.push(current);
        current = '';
        i++;
      }
    } else if (line[i] === ',') {
      fields.push(current);
      current = '';
      i++;
    } else {
      current += line[i];
      i++;
    }
  }

  fields.push(current);
  return fields;
}

