import json
import os
import glob

migrated = []
skipped = []

for path in glob.glob('configs/**/*.json', recursive=True):
    with open(path, 'r') as f:
        data = json.load(f)

    if data.get('version') == 2:
        skipped.append(path)
        continue

    # Migrate
    new_data = {}
    for key, value in data.items():
        if key == 'version':
            new_data['version'] = 2
        elif key == 'timeoutMs':
            new_data['timeout_s'] = value / 1000.0
        elif key == 'retry':
            new_data['retry'] = {
                'attempts': value['count'],
                'backoff_s': value['backoffMs'] / 1000.0
            }
        elif key == 'owners':
            if isinstance(value, str):
                emails = [email.strip().lower() for email in value.split(',')]
                emails = [email for email in emails if email]
                new_data['owners'] = emails
            else:
                new_data['owners'] = value
        else:
            new_data[key] = value

    # Ensure retry exists if missing
    if 'retry' not in new_data:
        new_data['retry'] = { 'attempts': 0, 'backoff_s': 0.0 }

    with open(path, 'w') as f:
        json.dump(new_data, f, indent=2)
        f.write('\n')
    migrated.append(path)

print('migrated:', len(migrated))
print('skipped (already v2):', len(skipped))
